function nav_groups(): array
{
    $g = [];
    foreach (mods() as $k => $m) {
        if (can($m['perm'] === 'admin' ? 'admin.manage' : $m['perm'] . '.view'))
            $g[$m['g']][] = ['k' => $k, 'n' => $m['n'], 'i' => $m['i'], 'h' => "modules/m.php?m=$k"];
    }
    if (can('reports.view')) {
        require_once __DIR__ . '/reports.php';
        foreach (report_defs() as $k => $r)
            $g['Reports'][] = ['k' => "r_$k", 'n' => $r['t'], 'i' => 'bar-chart', 'h' => "modules/reports.php?r=$k"];
    }
    if (can('admin.manage'))
        $g['Administration'][] = ['k' => 'settings', 'n' => 'Settings', 'i' => 'gear', 'h' => 'modules/settings.php'];
    return $g;
}
